UPDATE imphq_referencias
SET transcricao = 'Isso é o que o Vick Vaporub pode fazer pelo seu cérebro para você não acabar em um asilo por causa do Alzheimer. Não quero ser rude, mas estou explicando isso só mais uma vez antes que tentem derrubar meu vídeo. Amigos com mais de 50 anos, preste atenção. Hoje estou aqui para ajudar você a fazer o truque do Vick da maneira correta para reverter a perda de memória e se livrar rapidamente da névoa cerebral. Passei semanas tentando sem notar nenhuma melhora na minha memória, até que aprendi a ordem correta e a quantidade exata de cada ingrediente. Quando fiz da maneira certa, em três dias, me livrei da névoa cerebral. Senti uma clareza mental que não sentia há 30 anos. Em duas semanas, finalmente consegui manter uma conversa sem perder a linha de raciocínio no meio da frase, lembrando nomes e rostos, e parei de esquecer onde deixei meu celular antes de continuarmos. Um aviso importante: o vídeo com o passo a passo completo está disponível gratuitamente por apenas as próximas duas horas. Basta tocar no botão abaixo para copiar a receita correta antes que seja removida. Pessoal, voltei a fazer coisas que pessoas que só seguem recomendações de neurologistas nunca conseguiriam fazer, como ir ao supermercado sozinha, dirigir e ler um livro por semana. Foi a primeira vez em anos que me senti independente. E você sabe por que essa receita funciona? O segredo está em como seu corpo reage. O Vick elimina uma toxina silenciosa que se acumula no cérebro, e os outros dois ingredientes restauram a produção de neurotransmissores responsáveis pela memória. O resultado é uma mente afiada, protegida contra o Alzheimer e o declínio cognitivo. O passo a passo completo está aqui no botão abaixo. Em apenas 30 segundos, você aprenderá tudo. O vídeo é super rápido e já é um grande sucesso com mais de 23 milhões de visualizações. Você só precisa de três ingredientes simples que provavelmente já tem na sua geladeira para assistir. Toque no link aqui. O efeito é tão poderoso que muitas pessoas precisam parar de tomar Aricept e Memantina para evitar que a mente fique muito afiada. Nas próximas duas horas, você pode assistir isso 100% de graça. Mas corra, porque o vídeo também revela por que tomar Aricept ou Memantina pode estar sabotando a recuperação da sua memória e sua agilidade mental. Este vídeo já foi removido da internet sete vezes. Se ainda estiver disponível para você, toque agora e assista. Esta pode ser sua última chance de vê-lo de graça. Se você já tentou de tudo e nunca conseguiu recuperar sua memória, esta é sua oportunidade. Toque no botão abaixo, assista agora e prepare sua primeira xícara hoje. Prepare-se para sentir sua mente mais afiada até amanhã de manhã.',
    analise = '{"angle_family":"Truque de Cozinha / Solução Inesperada","caption":"Descubra o truque do Vick Vaporub para reverter a perda de memória e combater o declínio cognitivo.","criador":"MemoHoney","editorial":{"format":"UGC com Narração / Receita Simples","primaryNiche":"Memória","topic":"Este anúncio promove uma receita caseira usando Vick Vaporub e outros ingredientes para melhorar a memória e combater o Alzheimer, apresentada como uma solução fácil e poderosa que pode ser acessada por tempo limitado.","transfer":"Copiar a estrutura de testemunho pessoal com a urgência da remoção do vídeo, a revelação de um ''segredo'' usando um produto comum, e a oferta por tempo limitado para acessar a receita completa."},"anatomy":{"blocks":[{"start":0,"end":10,"kind":"hook","label":"Impacto do Vick no Cérebro","purpose":"Chocar o espectador com uma afirmação surpreendente sobre um produto comum para a saúde cerebral e criar curiosidade."},{"start":10,"end":18,"kind":"urgency","label":"Aviso de Censura e Chamada para Ação","purpose":"Criar urgência e exclusividade, indicando que o vídeo pode ser removido, e direcionar o público-alvo (''amigos com mais de 50 anos'')."},{"start":18,"end":28,"kind":"solution_introduction","label":"Apresentação do Truque do Vick","purpose":"Introduzir a solução principal (truque do Vick) para problemas de memória e névoa cerebral, posicionando-a como ''a maneira correta''."},{"start":28,"end":39,"kind":"personal_story","label":"Jornada Pessoal e Descoberta","purpose":"Criar conexão e credibilidade através de uma história pessoal de luta e sucesso após descobrir a ''ordem correta'' dos ingredientes."},{"start":39,"end":56,"kind":"results_demonstration","label":"Resultados Rápidos e Concretos","purpose":"Demonstrar os benefícios tangíveis e rápidos da solução (clareza mental, melhoria da memória, independência) para inspirar confiança e desejo."},{"start":56,"end":64,"kind":"scarcity_cta","label":"Urgência e Chamada para Ação","purpose":"Implantar escassez (''próximas duas horas'') e direcionar para uma ação imediata (tocar no botão para copiar a receita) antes que ela seja removida."},{"start":64,"end":74,"kind":"social_proof","label":"Prova Social e Impacto na Vida","purpose":"Mostrar exemplos de como a vida da pessoa melhorou, superando limitações que outras pessoas (seguindo neurologistas) não conseguem, reforçando a eficácia e a independência."},{"start":74,"end":88,"kind":"mechanism_explanation","label":"Explicação Científica Simplificada","purpose":"Explicar brevemente o ''porquê'' da eficácia da receita (eliminação de toxinas, restauração de neurotransmissores) para dar base lógica à promessa."},{"start":88,"end":96,"kind":"final_cta","label":"Chamada Final para Ação e Rapidez","purpose":"Reiterar a disponibilidade do passo a passo e enfatizar a rapidez com que a informação pode ser aprendida (30 segundos), incentivando o clique."},{"start":96,"end":105,"kind":"ease_of_use_and_popularity","label":"Facilidade e Popularidade","purpose":"Destacar a simplicidade dos ingredientes e a popularidade massiva do vídeo (milhões de visualizações) para aumentar a confiança e a prova social."},{"start":105,"end":113,"kind":"strong_effect_and_warning","label":"Efeito Poderoso e Alerta Médico","purpose":"Reforçar o poder da solução (pessoas param de tomar remédios) e criar intriga ao sugerir que medicamentos comuns podem ser prejudiciais, validando a alternativa."},{"start":113,"end":125,"kind":"renewed_urgency_and_controversy","label":"Urgência Renovada e Revelação Controversa","purpose":"Reiterar a escassez de tempo e adicionar um elemento controverso (sabotagem de remédios) para aumentar a curiosidade e o senso de que há algo a ser descoberto."},{"start":125,"end":133,"kind":"final_chance","label":"Última Chance e Chamada para Ação Desesperada","purpose":"Utilizar a tática da ''última chance'' (vídeo removido sete vezes) para induzir uma ação imediata por medo de perder a oportunidade."},{"start":133,"end":144.1,"kind":"ultimate_cta_and_future_promise","label":"Chamada Final com Promessa de Futuro","purpose":"Oferecer a solução como a última esperança para quem tentou de tudo, com uma chamada final direta e uma promessa de resultados rápidos para o dia seguinte."}]},"replication_prompt":"Crie um roteiro de vídeo de resposta direta focado em uma solução ''secreta'' e acessível para problemas de memória e declínio cognitivo. O roteiro deve começar com um gancho chocante sobre um produto comum (ex: sal, azeite) e seus efeitos cerebrais. Inclua uma narrativa pessoal de luta e descoberta da ''receita'' correta, com resultados rápidos e surpreendentes (ex: clareza mental em dias, lembrança de nomes em semanas). O vídeo deve criar urgência mencionando que a informação pode ser ''removida'' ou está disponível por tempo limitado, incentivando o clique imediato para uma ''receita completa'' que usa ingredientes simples que a maioria já tem em casa. Inclua uma explicação breve e simplificada do mecanismo de como a solução funciona no cérebro e uma forte CTA com a promessa de uma mente mais afiada em 24 horas."}'::jsonb,
