UPDATE imphq_referencias
SET transcricao = 'A recent study by Harvard neuroscientists proved that taking traditional medications or doing mental exercises does not solve the root cause of cognitive decline. The data revealed that the brain isn''t dying due to age. It is being suffocated by a metallic toxic rust that coats neurons and blocks electrical signals over the years. I am 80 years old and I completely banished that brain fog years ago. If I could do it, so can you. At 70, I lived through a senior''s worst nightmare. I would look at my partner across the dinner table and his name would slip my mind. I became completely disoriented while driving to the grocery store where I had worked for 40 years. I was loaded up on Aricept and Namenda. Nothing changed. I only got worse and seemed destined for isolation in a nursing home. My body wasn''t the problem. Harvard research uncovered the secret of centenarians in Okinawa who maintained perfect minds. They have zero toxic metal in their brains. The solution is a 15-second Japanese trick using a common kitchen ingredient, honey. When honey is combined with two inexpensive pantry staples, it acts as a potent natural biological solvent. This mixture chemically cleans and dissolves the toxic rust, allowing synapses to fire commands instantly again. It is a home-based method that is more powerful than Aricept for reversing advanced stage decline. My grandson saved me with this scientific discovery. By the fifth day, the brain fog had lifted. Within three weeks, I remembered and sang every verse of Unchained Melody, our honeymoon song. My husband wept and said, ''There you are, you''re back.'' Tap learn more below and watch the free video before nerve degeneration closes your biological window for recovery.',
    analise = '{"angle_family":"Inimigo Oculto","caption":"Um estudo de Harvard revela que a causa raiz do declínio cognitivo não é a idade, mas sim uma ferrugem tóxica que bloqueia os sinais elétricos no cérebro. Uma senhora de 80 anos descobriu uma solução caseira que inverte o declínio mental em semanas.","criador":"NeuroMemory","editorial":{"format":"UGC Storytelling","primaryNiche":"Memória","topic":"Este anúncio foca na causa subjacente do declínio cognitivo (ferrugem tóxica no cérebro) e apresenta uma solução natural, simples e eficaz que uma mulher idosa usou para reverter seu próprio declínio, restaurando sua memória em poucas semanas.","transfer":"Usar uma persona mais velha que superou um problema sério, detalhando a dificuldade que ela enfrentou. Apresentar uma nova causa subjacente para o problema. Oferecer uma solução natural e simples que rivaliza com os medicamentos farmacêuticos. Usar o ''honeymoon song'' para o ''aha moment''."},"anatomy":{"blocks":[{"start":0,"end":10,"kind":"hook","label":"Harvard revela a causa raiz do declínio cognitivo","purpose":"Chocar o espectador com a verdadeira causa do declínio cognitivo, que não é a idade, mas uma ''ferrugem tóxica'' no cérebro."},{"start":10,"end":19,"kind":"context","label":"Experiência pessoal com declínio cognitivo","purpose":"Apresentar a história pessoal da protagonista de 80 anos que superou o ''brain fog'' e, aos 70, vivenciou o pior pesadelo de um idoso (esquecer o nome do marido, desorientação)."},{"start":19,"end":26,"kind":"problem","label":"A ineficácia dos medicamentos tradicionais","purpose":"Demonstrar que os tratamentos médicos convencionais (Aricept e Namenda) foram ineficazes e a deixaram isolada."},{"start":26,"end":35,"kind":"discovery","label":"A pesquisa de Harvard e o segredo dos centenários de Okinawa","purpose":"Revelar a descoberta científica de Harvard sobre o segredo da longevidade mental dos centenários de Okinawa: a ausência de metal tóxico no cérebro."},{"start":35,"end":44,"kind":"solution","label":"A solução japonesa de 15 segundos: mel e ingredientes da despensa","purpose":"Apresentar a solução caseira: um truque japonês de 15 segundos com mel e outros itens da despensa que atua como um solvente biológico potente, limpando a ''ferrugem tóxica''."},{"start":44,"end":51,"kind":"mechanism","label":"Como a solução funciona","purpose":"Explicar como a mistura limpa quimicamente e dissolve a ferrugem, permitindo que as sinapses funcionem novamente, e como é mais poderosa que os medicamentos."},{"start":51,"end":64,"kind":"results","label":"Resultados transformadores da protagonista","purpose":"Detalhar os resultados dramáticos da protagonista: ''brain fog'' levantado em 5 dias, memorização de músicas e versos em 3 semanas, reunindo-se com o marido emocionalmente."},{"start":64,"end":70,"kind":"call_to_action","label":"Chamada para ação e urgência","purpose":"Incentivar o espectador a ''tocar em Saiba Mais'' e assistir a um vídeo gratuito antes que o declínio nervoso feche a ''janela biológica para a recuperação''."}]},"replication_prompt":"Crie um roteiro de vídeo estilo UGC onde um idoso (ou sua família) compartilha sua experiência com declínio cognitivo, atribuindo a causa a uma ''ferrugem tóxica'' no cérebro, citando pesquisas de Harvard. Mencione a ineficácia dos tratamentos tradicionais. Apresente uma solução natural, caseira e simples (inspirada em práticas japonesas com mel) que restaurou a memória e a clareza mental em semanas. Termine com um forte apelo à ação para assistir a um vídeo gratuito antes que seja tarde demais. Use uma música que lembre o passado ou o ''honeymoon song'' para criar um momento emocional."}'::jsonb,
    duracao = 94.6,
    transcribe_status = 'done',
    transcribe_provider = 'google/gemini-2.5-flash',
    transcribed_at = NOW(),
    updated_at = NOW()
WHERE id = 'e7f1add0-4671-4045-bda4-1ca194832dbb';

UPDATE imphq_referencias
SET transcricao = 'Decades with type two diabetes. Why didn''t anyone teach me this? You may not know this, but the biological reason why people struggle with type two has nothing to do with how many carbs or sugars you eat. A November 2023 study from the University of Dorf in Germany found that there are these sticky, protein-filled cells clogging up the part of the pancreas that produces insulin. So sugar builds up in the kidneys and is then forced back into your bloodstream, pushing your levels higher and higher. More importantly, these same scientists discovered a simple 10-second technique anyone can use starting tonight, which is now clinically proven to restore sugar levels back to normal, regardless of your age or current condition. All without medications, injections, strict diets or exercises. And it works like crazy. This natural bedtime hack is so confidential, the $90 billion diabetes treating industry is fighting to ban this video from the internet, as their entire business relies on your sugar levels never stabilizing as you get sicker and sicker, staying as a customer for life. More than 124,000 people of all ages are already using this natural solution and can finally control sugar levels even while eating their favorite foods. This ritual targets the root cause of type two. So once your sugar levels are stable, they are there to stay. I encourage you to stop what you''re doing right now and click the learn more button to watch a short free special video that shows exactly how you can use this ritual starting today to naturally restore and stabilize glucose levels and dissolve diabetic fat off your body for good. Remember, this has nothing to do with exercises, restrictive diets, injections or prescription medicines. And it doesn''t matter if you need to lose 10, 20 or 50 pounds of diabetic fat. Just imagine no more fingerpricks or feeling tired all the time. No more dealing with unexplained weight gain and living without the fear of kidney disease or heart issues. Best of all, you''ll finally be able to enjoy your favorite foods with your loved ones again. However, the billion dollar diabetes treating industry has already removed this special presentation from the internet twice before in a desperate attempt to protect their profits. So it''s uncertain how long the information will remain available this time. Tap the blue learn more button below before it''s too late.',
    analise = '{"angle_family":"Inimigo Oculto / Contraste de Preço","caption":"Estudo alemão descobre o motivo real do diabetes tipo 2 e um “truque” natural para revertê-lo que a indústria farmacêutica quer esconder.","criador":"Olivaro","editorial":{"format":"UGC Casual","primaryNiche":"Diabetes","topic":"Este criativo de vídeo revela um estudo alemão sobre a causa oculta do diabetes tipo 2 e um método natural de 10 segundos para estabilizar os níveis de açúcar no sangue, tudo isso enquanto denuncia a indústria bilionária do diabetes que tenta suprimir essa informação para proteger seus lucros.","transfer":"Copy: ''décadas com diabetes tipo 2, por que ninguém me ensinou isso?'' e ''Estudo de novembro de 2023 da Universidade de Dorf, na Alemanha''. Ambos aumentam a curiosidade e fornecem prova social. O problema oculto de ''células cheias de proteína'' é a revelação que prende o usuário. A escassez da oferta (''já foi retirado duas vezes da internet'') é um bom ponto de pressão. A promessa de ''sem medicamentos, injeções, dietas restritivas ou exercícios'' é muito poderosa."},"anatomy":{"blocks":[{"start":0,"end":9.9,"kind":"hook","label":"Gatilho de curiosidade e validação","purpose":"Começa com uma pergunta intrigante e empática, validando a frustração do público com o tratamento atual do diabetes e apresentando a promessa de uma nova informação."},{"start":9.9,"end":35.7,"kind":"problem","label":"O verdadeiro problema do diabetes tipo 2","purpose":"Desafia a crença comum sobre a causa do diabetes, introduzindo uma nova e ''científica'' explicação sobre as células pegajosas que impedem a produção de insulina, criando um novo ''inimigo'' e gerando mais curiosidade."},{"start":35.7,"end":64.6,"kind":"solution","label":"Solução oculta e promessa de liberdade","purpose":"Apresenta um método simples e eficaz de 10 segundos para restaurar os níveis de açúcar no sangue, destacando que não envolve medicamentos, injeções ou dietas rigorosas. Promete liberdade das restrições atuais, atingindo um desejo profundo da audiência."},{"start":64.6,"end":84,"kind":"resistance","label":"A conspiração da indústria bilionária","purpose":"Revela que a indústria do diabetes está ativamente tentando suprimir essa informação, posicionando o método como uma ameaça aos seus lucros e criando um senso de urgência e exclusividade sobre a informação."},{"start":84,"end":102.3,"kind":"proof","label":"Prova social e benefícios ampliados","purpose":"Fornece prova social com o número de pessoas usando o método e reforça os benefícios, como controle dos níveis de açúcar mesmo comendo comidas favoritas, e aborda a causa raiz da doença."},{"start":102.3,"end":133,"kind":"call_to_action","label":"Chamada para ação clara e reafirmação dos benefícios","purpose":"Instrui o usuário a clicar para aprender mais sobre o ritual, reiterando que ele dissolve gordura diabética e não exige sacrifícios. Reforça os benefícios de longo prazo e a melhoria da qualidade de vida."},{"start":133,"end":145.4,"kind":"urgency","label":"Urgência e escassez final","purpose":"Cria um forte senso de urgência ao informar que a indústria já removeu a apresentação antes, incentivando a ação imediata para acessar a informação antes que seja tarde."}]},"replication_prompt":"Crie um roteiro de vídeo no estilo UGC casual para um produto que ajuda a controlar o diabetes. O roteiro deve começar com um gancho emocional, mencionar um ''segredo'' ou ''estudo recente'' que a indústria farmacêutica quer esconder, apresentar uma solução natural simples que não envolve exercícios, dietas ou medicamentos, e terminar com uma forte chamada para ação com senso de urgência. Use uma linguagem empática e de confronto, destacando a frustração do público com os tratamentos convencionais."}'::jsonb,
    duracao = 145.4,
    transcribe_status = 'done',
    transcribe_provider = 'google/gemini-2.5-flash',
    transcribed_at = NOW(),
    updated_at = NOW()
WHERE id = 'e8766c3f-dd5e-4f8b-a745-7646a283da1d';

UPDATE imphq_referencias
SET transcricao = 'You can''t eat apples, spinach, chicken, yogurt, and it will not clear what has been sitting inside you for years. Let me show you what actually works. Get a pot of water boiling, chop up a fresh lemon, and drop it in. Add one teaspoon of chia seed, a teaspoon of turmeric, and finish it with a pinch of black pepper. Let it boil for 10 minutes, then strain it out. This wakes your entire system up, bloating gone, gut cleaned right out, and your body is left feeling lighter and happier. But this is only one small part of what I discovered. If you''re concerned about your blood sugar, there''s another simple approach you should know about. I put together a short video explaining what I learned, why so many people overlook it, and the simple daily habit behind it. Tap the button below and watch the video now. It only takes a few minutes, and what you discover may completely change the way you think about supporting healthy blood sugar.',
    analise = '{"angle_family":"Segredo de Despensa","caption":"A receita caseira de um minuto para a saúde do açúcar no sangue.","criador":"GlycoBarrier","editorial":{"format":"UGC Casual","primaryNiche":"Diabetes","topic":"Este vídeo apresenta uma bebida caseira que supostamente \"limpa\" o sistema e combate o inchaço. Em seguida, ele leva a uma \"abordagem simples\" para o açúcar no sangue, presumivelmente levando ao produto.","transfer":"Comece com um ritual caseiro que \"funciona\" para o nicho de saúde, o que leva a uma solução mais abrangente e definitiva para o problema."},"anatomy":{"blocks":[{"start":0,"end":10,"kind":"hook","label":"Problema e falsa solução","purpose":"Apresenta uma falsa solução (comida saudável) e depois o problema real (não limpa o sistema por dentro)."},{"start":10,"end":35,"kind":"solution_show","label":"Receita do segredo da despensa","purpose":"Demonstra a solução da receita da despensa para o problema e como ela o faz se sentir melhor."},{"start":35,"end":44,"kind":"bridge","label":"Apresentando o verdadeiro segredo","purpose":"A receita da despensa é apenas uma pequena parte do que o narrador descobriu, levando a uma abordagem melhor para a saúde do açúcar no sangue."},{"start":44,"end":55.6,"kind":"cta","label":"Chamada para ação","purpose":"Um CTA simples e direto para clicar para descobrir mais e assistir a um vídeo explicando."}]},"replication_prompt":"Crie um vídeo no estilo UGC sobre uma receita caseira que \"limpa\" o sistema e ajuda no inchaço. O narrador deve então dizer que isso é apenas uma pequena parte do que eles descobriram e levá-los a uma \"abordagem simples\" para o açúcar no sangue (suponha que seja um produto GlycoBarrier)."}'::jsonb,
    duracao = 55.6,
    transcribe_status = 'done',
    transcribe_provider = 'google/gemini-2.5-flash',
    transcribed_at = NOW(),
    updated_at = NOW()
